def replay_portfolio(events,initial_cash,marks):
    # One synthetic account/currency, symbols A/B, flat at start; economic cash.
    if type(initial_cash) is not int or not 0<=initial_cash<=1000000000:
        raise ValueError("expected bounded integer starting cash cents")
    if type(marks) is not dict or set(marks)!={"A","B"} or any(type(p) is not int or not 1<=p<=1000000 for p in marks.values()):
        raise ValueError("expected positive integer marks for exactly A and B")
    if type(events) is not list or len(events)>1000:
        raise ValueError("expected at most1000confirmed execution records")
    cash=initial_cash;positions={"A":0,"B":0};seen={};duplicates=0;fees=0
    for row in events:
        if type(row) is not tuple or len(row)!=5:
            raise ValueError("expected(execution_id,symbol,signed_quantity,price_cents,fee_cents)")
        eid,symbol,delta,price,fee=row
        if type(eid) is not str or not eid or len(eid)>30 or type(symbol) is not str or symbol not in positions:
            raise ValueError("invalid execution identity or symbol")
        if type(delta) is not int or not 1<=abs(delta)<=1000000 or type(price) is not int or not 1<=price<=1000000 or type(fee) is not int or not 0<=fee<=1000000:
            raise ValueError("invalid bounded integer quantity/price/fee")
        payload=(symbol,delta,price,fee)
        if eid in seen:
            if seen[eid]!=payload:
                raise ValueError("conflicting duplicate execution id")
            duplicates+=1
            continue
        seen[eid]=payload
        positions[symbol]+=delta
        cash-=delta*price+fee
        fees+=fee
    marked_value=sum(positions[symbol]*marks[symbol] for symbol in positions)
    return {"cash":cash,"positions":positions,"fees":fees,"equity":cash+marked_value,
            "net_pnl":cash+marked_value-initial_cash,"applied":len(seen),"duplicates":duplicates}

records=[("E1","A",10,1000,2),("E2","B",4,2000,3),("E3","A",-3,1100,1)]
print(replay_portfolio(records+[records[0]],100000,{"A":1050,"B":1900}))
try:
    replay_portfolio(records+[("E1","A",11,1000,2)],100000,{"A":1050,"B":1900})
except ValueError:
    print("conflicting duplicate rejected")

