# Independent reconciler assumes authoritative statement and separately deduplicated raw fills.
records=[("E1","A",10,1000,2),("E2","B",4,2000,3),("E3","A",-3,1100,1)]
result=replay_portfolio(records,100000,{"A":1050,"B":1900})
expected_cash=100000-sum(row[2]*row[3]+row[4] for row in records)
expected_positions={s:sum(row[2] for row in records if row[1]==s) for s in ("A","B")}
assert result["cash"]==expected_cash and result["positions"]==expected_positions
statement_cash=85294;statement_positions={"A":7,"B":4}
print(statement_cash-result["cash"])
print({s:statement_positions[s]-result["positions"][s] for s in ("A","B")})
# A deliberate cash discrepancy is reported, not repaired.
print((statement_cash+2)-result["cash"])
print(replay_portfolio(records+records,100000,{"A":1050,"B":1900})["cash"]==result["cash"])
